mapper.select:
SELECT FROM chat_conversation WHERE 1 = 1
AND user_id = #{userId}
AND guest_key = #{guestKey}
ORDER BY conversation_id DESC LIMIT 1

mapper.update:
UPDATE chat_conversation
   SET status = 'WAITING_AGENT'
     , last_message_at = #{now}
 WHERE conversation_id = #{conversationId}
   AND status IN ('BOT', 'WAITING_AGENT', 'IN_PROGRESS')

UPDATE chat_conversation
   SET status = 'AI_ANSWERED'
     , last_message_at = #{now}
 WHERE conversation_id = #{conversationId}
   AND status = 'WAITING_AGENT'

UPDATE chat_conversation
   SET ai_answer_count = ai_answer_count + 1
 WHERE conversation_id = #{conversationId}
   AND ai_answer_count < #{limit}
   AND status != 'CLOSED'

UPDATE chat_conversation
   SET status = 'IN_PROGRESS'
     , assigned_admin_id = COALESCE(assigned_admin_id, #{assignedAdminId})
     , last_message_at = #{now}
 WHERE conversation_id = #{conversationId}
   AND status != 'CLOSED'

UPDATE chat_conversation
   SET status = 'CLOSED'
     , closed_at = #{now}
 WHERE conversation_id = #{conversationId}
   AND status != 'CLOSED'

UPDATE chat_conversation
   SET last_message_at = #{now}
 WHERE conversation_id = #{conversationId}

UPDATE chat_conversation
   SET user_id = #{userId}
 WHERE conversation_id = #{conversationId}
   AND user_id IS NULL
   AND guest_key = #{guestKey}
